    v_id := (public.upsert_tracks(jsonb_build_array(a -> 'track')))[1];
    v_ids := v_ids || v_id;

    update public.tracks set language = case when a ->> 'lang' = '-' then 'zxx' else a ->> 'lang' end
    where id = v_id;

    insert into public.track_features (track_id, energy, valence, acoustic, tempo, dance, complexity, vocal, bass, polish, warmth, era, niche, genre_weights, source, confidence, details)
    values (v_id, (a -> 'features' ->> 'energy')::real, (a -> 'features' ->> 'valence')::real, (a -> 'features' ->> 'acoustic')::real, (a -> 'features' ->> 'tempo')::real, (a -> 'features' ->> 'dance')::real, (a -> 'features' ->> 'complexity')::real, (a -> 'features' ->> 'vocal')::real, (a -> 'features' ->> 'bass')::real, (a -> 'features' ->> 'polish')::real, (a -> 'features' ->> 'warmth')::real, (a -> 'features' ->> 'era')::real, (a -> 'features' ->> 'niche')::real, a -> 'genres', 'curated', (a ->> 'confidence')::real,
            jsonb_build_object('anchor', true, 'generated_at', '2026-10-28T23:40:10.781Z'))
    on conflict (track_id) do update
      set energy = excluded.energy, valence = excluded.valence, acoustic = excluded.acoustic, tempo = excluded.tempo, dance = excluded.dance, complexity = excluded.complexity, vocal = excluded.vocal, bass = excluded.bass, polish = excluded.polish, warmth = excluded.warmth, era = excluded.era, niche = excluded.niche, genre_weights = excluded.genre_weights, confidence = excluded.confidence,
          details = public.track_features.details || excluded.details, updated_at = now()
      where public.track_features.source in ('curated', 'estimated');

    insert into public.anchor_tracks (track_id, cell, active)
    values (v_id, a ->> 'cell', true)
    on conflict (track_id) do update set cell = excluded.cell, active = true;
  end loop;

  -- Les ancres retirées de la source sont désactivées (jamais supprimées).
  update public.anchor_tracks set active = false where not (track_id = any (v_ids));

  raise notice 'Bibliothèque d''ancrage : % morceaux chargés.', array_length(v_ids, 1);
end $do$;
